package com.finsight.domain; import jakarta.persistence.*; @Entity public class Customer { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String companyName,industry; Double annualRevenue,ebitda,totalDebt,cashBalance; Integer paymentHistoryScore; public Long getId(){return id;} public String getCompanyName(){return companyName;} public String getIndustry(){return industry;} public Double getAnnualRevenue(){return annualRevenue;} public Double getEbitda(){return ebitda;} public Double getTotalDebt(){return totalDebt;} public Double getCashBalance(){return cashBalance;} public Integer getPaymentHistoryScore(){return paymentHistoryScore;} public void setCompanyName(String v){companyName=v;} public void setIndustry(String v){industry=v;} public void setAnnualRevenue(Double v){annualRevenue=v;} public void setEbitda(Double v){ebitda=v;} public void setTotalDebt(Double v){totalDebt=v;} public void setCashBalance(Double v){cashBalance=v;} public void setPaymentHistoryScore(Integer v){paymentHistoryScore=v;} }
